/**
 * Bounded-concurrency map with stable ordering, failure draining and
 * AbortSignal cancellation.
 *
 * @param {Array} items input items (never mutated)
 * @param {number} limit positive integer, max workers in flight
 * @param {(item: any, index: number, signal: AbortSignal|undefined) => any} worker
 * @param {{signal?: AbortSignal}} [options]
 * @returns {Promise<Array>} results in input order
 */
function validateArguments(items, limit, worker) {
  if (!Array.isArray(items)) {
    throw new TypeError('mapLimit: items must be an array');
  }
  if (!Number.isInteger(limit) || limit <= 0) {
    throw new TypeError('mapLimit: limit must be a positive integer');
  }
  if (typeof worker !== 'function') {
    throw new TypeError('mapLimit: worker must be a function');
  }
}

function readSignal(options) {
  if (options === null || typeof options !== 'object') return undefined;
  return options.signal;
}

async function mapLimit(items, limit, worker, options = {}) {
  // Validate before any worker can run, including for empty input.
  validateArguments(items, limit, worker);

  const signal = readSignal(options);
  const total = items.length;

  // Abort wins over "empty input resolves []".
  if (signal && signal.aborted) {
    // Preserve identity of the reason, including falsy/non-Error values.
    throw signal.reason;
  }

  if (total === 0) return [];

  const results = new Array(total);

  return new Promise((resolve, reject) => {
    let nextIndex = 0;
    let inFlight = 0;
    let finished = false;
    let failed = false;
    let failureReason;

    const canListen = Boolean(signal) && typeof signal.addEventListener === 'function';

    function onAbort() {
      if (finished || failed) return;
      // First observed failure/abort wins.
      failed = true;
      failureReason = signal.reason;
      // Stop scheduling; in-flight work is drained before settling.
      schedule();
    }

    const cleanup = () => {
      if (canListen) signal.removeEventListener('abort', onAbort);
    };

    const finish = () => {
      if (finished) return;
      finished = true;
      cleanup();
      if (failed) reject(failureReason);
      else resolve(results);
    };

    const recordFailure = (reason) => {
      if (failed) return;
      failed = true;
      failureReason = reason;
    };

    function schedule() {
      if (finished) return;
      // Fill every available slot; never exceed `limit`.
      while (!failed && inFlight < limit && nextIndex < total) {
        start(nextIndex++);
      }
      if (failed) {
        if (inFlight === 0) finish();
        return;
      }
      if (nextIndex >= total && inFlight === 0) finish();
    }

    function start(index) {
      inFlight += 1;
      let outcome;
      try {
        outcome = worker(items[index], index, signal);
      } catch (error) {
        settle(index, error, true);
        return;
      }
      // Handlers are attached immediately so secondary failures can never
      // surface as unhandled rejections.
      Promise.resolve(outcome).then(
        (value) => settle(index, value, false),
        (error) => settle(index, error, true),
      );
    }

    function settle(index, value, isFailure) {
      inFlight -= 1;
      if (isFailure) recordFailure(value);
      else results[index] = value;
      schedule();
    }

    if (canListen) signal.addEventListener('abort', onAbort);
    schedule();
  });
}

module.exports = {mapLimit};
"}

{"path": "lib/batch.cjs", "content": "'use strict';

const {mapLimit} = require('./pool.cjs');

const DEFAULT_CONCURRENCY = 2;

/**
 * Sends every record at most once with bounded concurrency and returns
 * `{id, value}` records in input order.
 *
 * @param {Array<{id: any}>} records
 * @param {(record: any, index: number, signal: AbortSignal|undefined) => any} send
 * @param {{concurrency?: number, signal?: AbortSignal}} [options]
 * @returns {Promise<Array<{id: any, value: any}>>}
 */
function processBatch(records, send, options = {}) {
  const settings = options === null || typeof options !== 'object' ? {} : options;
  const concurrency =
    settings.concurrency === undefined ? DEFAULT_CONCURRENCY : settings.concurrency;

  return mapLimit(
    records,
    concurrency,
    async (record, index, signal) => ({id: record.id, value: await send(record, index, signal)}),
    {signal: settings.signal},
  );
}

module.exports = {processBatch};
"}

{"content": "'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const {mapLimit} = require('../index.cjs');

const tick = () => new Promise((resolve) => setImmediate(resolve));

test('maps values and preserves falsy results', async () => {
  assert.deepEqual(await mapLimit([1, 2], 2, (x) => x - 1), [0, 1]);
});

test('empty input', async () => {
  assert.deepEqual(await mapLimit([], 2, (x) => x), []);
});

test('empty input still validates arguments', async () => {
  await assert.rejects(() => mapLimit([], 0, () => 1), TypeError);
  await assert.rejects(() => mapLimit([], -1, () => 1), TypeError);
  await assert.rejects(() => mapLimit('nope', 2, () => 1), TypeError);
  await assert.rejects(() => mapLimit([], 2, 'nope'), TypeError);
  await assert.rejects(() => mapLimit([], 2.5, () => 1), TypeError);
});

test('validates before invoking any worker', async () => {
  let called = 0;
  await assert.rejects(
    () =>
      mapLimit([1, 2], 0, () => {
        called += 1;
        return 1;
      }),
    TypeError,
  );
  assert.equal(called, 0);
});

test('results are in input order even when completion order differs', async () => {
  const delays = [30, 1, 20, 2];
  const results = await mapLimit([0, 1, 2, 3], 2, async (index) => {
    await new Promise((resolve) => setTimeout(resolve, delays[index]));
    return `v${index}`;
  });
  assert.deepEqual(results, ['v0', 'v1', 'v2', 'v3']);
});

test('does not mutate the input array', async () => {
  const items = [3, 1, 2];
  const copy = items.slice();
  await mapLimit(items, 2, (x) => x * 2);
  assert.deepEqual(items, copy);
});

test('never exceeds the concurrency limit and fills available slots', async () => {
  let inFlight = 0;
  let peak = 0;
  const started = [];
  const results = await mapLimit([1, 2, 3, 4, 5, 6], 3, async (item) => {
    inFlight += 1;
    peak = Math.max(peak, inFlight);
    started.push(item);
    if (started.length === 3) {
      // All three initial slots must be started before any of them finish.
      assert.deepEqual(started.slice(0, 3), [1, 2, 3]);
    }
    await tick();
    inFlight -= 1;
    return item * 10;
  });
  assert.equal(peak, 3);
  assert.deepEqual(results, [10, 20, 30, 40, 50, 60]);
});

test('starts each item exactly once', async () => {
  const seen = [];
  await mapLimit([1, 2, 3, 4], 2, (item) => {
    seen.push(item);
    return item;
  });
  assert.deepEqual(seen.slice().sort((a, b) => a - b), [1, 2, 3, 4]);
});

test('worker receives item, index and signal', async () => {
  const controller = new AbortController();
  const observed = [];
  await mapLimit(['a', 'b'], 1, (item, index, signal) => {
    observed.push([item, index, signal]);
    return item;
  }, {signal: controller.signal});
  assert.deepEqual(observed.map(([item, index]) => [item, index]), [['a', 0], ['b', 1]]);
  assert.equal(observed[0][2], controller.signal);
});

test('supports synchronous workers and synchronous throws', async () => {
  assert.deepEqual(await mapLimit([1, 2], 2, (x) => x + 1), [2, 3]);
  const boom = new Error('sync');
  await assert.rejects(() => mapLimit([1], 1, () => { throw boom; }), (error) => error === boom);
});

test('drains in-flight work and rejects with the first observed error', async () => {
  const first = new Error('first');
  const second = new Error('second');
  const settled = [];
  let started = 0;

  await assert.rejects(
    () =>
      mapLimit([0, 1, 2, 3], 2, async (index) => {
        started += 1;
        if (index === 0) {
          await tick();
          throw first;
        }
        if (index === 1) {
          await new Promise((resolve) => setTimeout(resolve, 20));
          throw second;
        }
        settled.push(index);
        return index;
      }),
    (error) => error === first,
  );

  // Item 0 failed first, so items 2 and 3 must never be started.
  assert.equal(started, 2);
  assert.deepEqual(settled, []);
});

test('secondary failures do not cause unhandled rejections', async () => {
  const unhandled = [];
  const onUnhandled = (reason) => unhandled.push(reason);
  process.on('unhandledRejection', onUnhandled);
  try {
    const first = new Error('first');
    await assert.rejects(
      () => mapLimit([0, 1], 2, async (index) => {
        await tick();
        throw index === 0 ? first : new Error('secondary');
      }),
      (error) => error === first,
    );
    await new Promise((resolve) => setTimeout(resolve, 20));
  } finally {
    process.removeListener('unhandledRejection', onUnhandled);
  }
  assert.deepEqual(unhandled, []);
});

test('already-aborted signal starts no work and rejects with the reason', async () => {
  const controller = new AbortController();
  const reason = new Error('cancelled');
  controller.abort(reason);
  let called = 0;
  await assert.rejects(
    () => mapLimit([1, 2], 2, (x) => { called += 1; return x; }, {signal: controller.signal}),
    (error) => error === reason,
  );
  assert.equal(called, 0);
});

test('already-aborted signal preserves a non-Error reason', async () => {
  const controller = new AbortController();
  controller.abort('stop');
  await assert.rejects(
    () => mapLimit([1], 1, (x) => x, {signal: controller.signal}),
    (error) => error === 'stop',
  );
});

test('already-aborted signal wins over empty input', async () => {
  const controller = new AbortController();
  controller.abort(42);
  await assert.rejects(
    () => mapLimit([], 2, (x) => x, {signal: controller.signal}),
    (error) => error === 42,
  );
});

test('mid-run abort stops scheduling, drains in-flight work and rejects', async () => {
  const controller = new AbortController();
  const reason = new Error('mid-run');
  const completed = [];
  let started = 0;

  const promise = mapLimit([0, 1, 2, 3, 4], 2, async (index) => {
    started += 1;
    await new Promise((resolve) => setTimeout(resolve, 10));
    completed.push(index);
    return index;
  }, {signal: controller.signal});

  setTimeout(() => controller.abort(reason), 5);

  await assert.rejects(() => promise, (error) => error === reason);
  assert.equal(started, 2);
  assert.deepEqual(completed.slice().sort((a, b) => a - b), [0, 1]);
});

test('no abort listener is left installed after settlement', async () => {
  const controller = new AbortController();
  const {signal} = controller;
  const original = signal.removeEventListener.bind(signal);
  let removed = 0;
  signal.removeEventListener = (...args) => {
    removed += 1;
    return original(...args);
  };
  try {
    await mapLimit([1, 2, 3], 3, (x) => x, {signal});
    assert.equal(removed, 1);
  } finally {
    delete signal.removeEventListener;
  }
});
